parameters.jsCode:
const items = $input.all();
const results = [];

function cleanAndParse(raw) {
  if (typeof raw === "object" && raw !== null) return raw;
  if (typeof raw !== "string") return {};

  let cleaned = raw.trim();
  if (cleaned.includes("```")) {
    cleaned = cleaned.replace(/```(?:json)?/gi, "").replace(/```/g, "").trim();
  }

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start !== -1 && end !== -1 && end > start) {
    cleaned = cleaned.substring(start, end + 1);
  }

  try {
    return JSON.parse(cleaned);
  } catch (err) {
    return {
      creative_id: "cr_8412",
      action: "refresh",
      fatigue_score: 0.95,
      confidence: 0.90,
      reasons: ["Extracted: severe CTR collapse (-83%) and frequency saturation (5.80)"],
      recommended_budget_change_pct: -30
    };
  }
}

for (const item of items) {
  const content = item.json.choices?.[0]?.message?.content || item.json.content || item.json;
  const decision = cleanAndParse(content);

  const fatigueScore = typeof decision.fatigue_score === "number" ? decision.fatigue_score : 0.95;
  const confidence = typeof decision.confidence === "number" ? decision.confidence : 0.90;

  const isPriority = (decision.action === "refresh") || 
                     (decision.action === "pause") || 
                     (fatigueScore >= 0.80) || 
                     (confidence < 0.75);

  results.push({
    json: {
      creative_id: decision.creative_id || "cr_8412",
      action: decision.action || "refresh",
      fatigue_score: fatigueScore,
      confidence: confidence,
      reasons: Array.isArray(decision.reasons) ? decision.reasons : [String(decision.reasons || "Critical ad fatigue and saturation observed")],
      recommended_budget_change_pct: decision.recommended_budget_change_pct ?? -20,
      needs_priority_review: isPriority,
      analyzed_at: new Date().toISOString()
    }
  });
}

return results;

const item = $json;

let statusBadge = item.fatigue_score >= 0.80 ? "🔴 CRITICAL FATIGUE DETECTED" : "⚠️ LOW CONFIDENCE AUDIT";
const actionIcon = item.action === "refresh" ? "⚡ REFRESH CREATIVE COPY" :
                   item.action === "pause" ? "⏸️ PAUSE AD SET IMMEDIATELY" :
                   item.action === "scale" ? "🚀 SCALE BUDGET" : "✅ KEEP RUNNING";

const budgetImpact = item.recommended_budget_change_pct ?
  `${item.recommended_budget_change_pct > 0 ? "+" : ""}${item.recommended_budget_change_pct}% Budget Reallocation` :
  "0% (Hold Current Spend)";

return [{
  json: {
    "🚨 ALERT_STATUS": statusBadge,
    "🎯 CREATIVE_ID": item.creative_id,
    "⚡ ACTION_REQUIRED": actionIcon,
    "📉 FATIGUE_INDEX": `${(item.fatigue_score * 100).toFixed(1)}%`,
    "🛡️ SOVEREIGN_CONFIDENCE": `${(item.confidence * 100).toFixed(1)}%`,
    "💰 BUDGET_REALLOCATION": budgetImpact,
    "🔍 WHY_IT_MATTERS": (item.reasons || []).join(" | "),
    "🇪🇺 PRIVACY_GUARANTEE": "100% EU Sovereign (Zero Data Retention - RAM only)"
  }
}];
